{"name": "write_file", "arguments": {"path": "install.js", "content": "#!/usr/bin/env node
/**
 * install.js - AgentMemory Installation Script
 * 
 * This script handles installation and setup of AgentMemory with support for:
 * - Docker-based installation (original method)
 * - Local PostgreSQL installation (new default method)
 * - Cross-platform support (Windows, Linux, Mac)
 * - MCP endpoint testing and validation
 * 
 * Usage:
 *   node install.js [docker|local] [options]
 * 
 * Examples:
 *   node install.js                    # Auto-detect and install
 *   node install.js local              # Install with local PostgreSQL
 *   node install.js docker             # Install with Docker (original method)
 *   node install.js local --skip-db    # Skip database setup
 *   node install.js local --test-mcp   # Test MCP endpoints after install
 */

const fs = require('fs');
const path = require('path');
const { execSync, exec } = require('child_process');
const os = require('os');

// Configuration
const CONFIG = {
  postgres: {
    host: 'localhost',
    port: 5432,
    database: 'agent_memory',
    user: 'postgres',
    password: process.env.POSTGRES_PASSWORD || 'postgres'
  },
  mcp: {
    port: 3377,
    url: 'http://localhost:3377'
  },
  models: {
    embeddings: 'nomic-embed-text-v1.5',
    llm: process.env.ANVIL_MODEL || 'qwen3.5'
  }
};

// Platform detection
const PLATFORM = {
  isWindows: process.platform === 'win32',
  isMac: process.platform === 'darwin',
  isLinux: process.platform === 'linux'
};

// Color output
const colors = {
  reset: '\x1b[0m',
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  cyan: '\x1b[36m',
  white: '\x1b[37m'
};

const log = {
  info: (msg) => console.log(`${colors.cyan}[INFO]${colors.reset} ${msg}`),
  success: (msg) => console.log(`${colors.green}✓${colors.reset} ${msg}`),
  warn: (msg) => console.log(`${colors.yellow}[WARN]${colors.reset} ${msg}`),
  error: (msg) => console.log(`${colors.red}[ERROR]${colors.reset} ${msg}`),
  step: (msg) => console.log(`${colors.blue}[STEP]${colors.reset} ${msg}`)
};

/**
 * Check if a command exists
 */
function commandExists(cmd) {
  try {
    execSync(`command -v ${cmd}`, { stdio: 'pipe' });
    return true;
  } catch (e) {
    return false;
  }
}

/**
 * Check if Docker is available
 */
function checkDocker() {
  try {
    const output = execSync('docker --version', { encoding: 'utf8' });
    return { available: true, version: output };
  } catch (e) {
    return { available: false, error: e.message };
  }
}

/**
 * Check if PostgreSQL is available
 */
function checkPostgres() {
  try {
    const output = execSync(`psql --version`, { encoding: 'utf8' });
    return { available: true, version: output };
  } catch (e) {
    return { available: false, error: e.message };
  }
}

/**
 * Check if Python is available
 */
function checkPython() {
  try {
    const output = execSync('python3 --version', { encoding: 'utf8' });
    return { available: true, version: output };
  } catch (e) {
    return { available: false, error: e.message };
  }
}

/**
 * Install PostgreSQL on Linux
 */
function installPostgresLinux() {
  log.step('Installing PostgreSQL on Linux...');

  try {
    execSync('sudo apt-get update', { stdio: 'inherit' });
    execSync('sudo apt-get install -y postgresql postgresql-contrib', { stdio: 'inherit' });
    log.success('PostgreSQL installed successfully');
    return true;
  } catch (e) {
    log.error('Failed to install PostgreSQL on Linux');
    return false;
  }
}

/**
 * Install PostgreSQL on macOS
 */
function installPostgresMac() {
  log.step('Installing PostgreSQL on macOS...');

  try {
    // Check if Homebrew is available
    if (!commandExists('brew')) {
      log.warn('Homebrew not found. Installing Homebrew...');
      execSync('/bin/bash -c "$(curl -fsSL https://raw.githubusercontent.com/Homebrew/install/HEAD/install.sh)"', { stdio: 'inherit' });
    }

    execSync('brew install postgresql', { stdio: 'inherit' });
    log.success('PostgreSQL installed successfully');
    return true;
  } catch (e) {
    log.error('Failed to install PostgreSQL on macOS');
    return false;
  }
}

/**
 * Install PostgreSQL on Windows
 */
function installPostgresWindows() {
  log.step('Installing PostgreSQL on Windows...');

  try {
    // Download and install PostgreSQL installer
    const installerUrl = 'https://download.postgresql.org/pub/release/binaries/postgresql-16/binaries/windows/postgresql-16-4-windows-x64.exe';
    const installerPath = path.join(os.homedir(), 'postgresql-installer.exe');

    log.info('Downloading PostgreSQL installer...');
    // Note: On Windows, users may need to download manually or use winget
    log.warn('On Windows, you may need to download PostgreSQL manually from:');
    log.warn('https://www.postgresql.org/download/windows/');
    log.warn('Or use winget: winget install PostgreSQL.PostgreSQL');

    return true;
  } catch (e) {
    log.error('Failed to install PostgreSQL on Windows');
    return false;
  }
}

/**
 * Start PostgreSQL service
 */
function startPostgres() {
  log.step('Starting PostgreSQL service...');

  try {
    if (PLATFORM.isLinux) {
      execSync('sudo systemctl start postgresql', { stdio: 'pipe' });
    } else if (PLATFORM.isMac) {
      execSync('brew services start postgresql', { stdio: 'pipe' });
    } else if (PLATFORM.isWindows) {
      execSync('pg_ctl -D "C:\\Program Files\\PostgreSQL\\16\\data" start', { stdio: 'pipe' });
    }
    log.success('PostgreSQL service started');
    return true;
  } catch (e) {
    log.warn('Could not start PostgreSQL service automatically');
    log.info('Please start PostgreSQL manually:');
    log.info('  Linux: sudo systemctl start postgresql');
    log.info('  Mac: brew services start postgresql');
    log.info('  Windows: pg_ctl -D "C:\\Program Files\\PostgreSQL\\16\\data" start');
    return false;
  }
}

/**
 * Initialize PostgreSQL database
 */
function initPostgres() {
  log.step('Initializing PostgreSQL database...');

  try {
    // Create database
    execSync(`psql -U postgres -c "CREATE DATABASE ${CONFIG.postgres.database};"`, { stdio: 'pipe' });

    // Create user if not exists
    execSync(`psql -U postgres -c "DO \$\$\nCREATE USER IF NOT EXISTS ${CONFIG.postgres.user} WITH PASSWORD '${CONFIG.postgres.password}';\nGRANT ALL PRIVILEGES ON DATABASE ${CONFIG.postgres.database} TO ${CONFIG.postgres.user};\n\$\$;"`, { stdio: 'pipe' });

    log.success('Database initialized successfully');
    return true;
  } catch (e) {
    log.error('Failed to initialize PostgreSQL database');
    return false;
  }
}

/**
 * Install Python dependencies
 */
function installPythonDependencies() {
  log.step('Installing Python dependencies...');

  try {
    const venvPath = path.join(process.cwd(), '.venv');

    // Create virtual environment if it doesn't exist
    if (!fs.existsSync(venvPath)) {
      log.info('Creating virtual environment...');
      execSync('python3 -m venv .venv', { stdio: 'inherit' });
    }

    // Activate virtual environment
    const activateCmd = PLATFORM.isWindows ? '.venv\Scripts\activate.bat' : '.venv/bin/activate';
    execSync(`source ${activateCmd} && pip install --upgrade pip`, { stdio: 'inherit' });

    // Install dependencies
    execSync('source .venv/bin/activate && pip install -e ".[dev]"', { stdio: 'inherit' });

    log.success('Python dependencies installed successfully');
    return true;
  } catch (e) {
    log.error('Failed to install Python dependencies');
    return false;
  }
}

/**
 * Test MCP endpoints
 */
async function testMCPEndpoints() {
  log.step('Testing MCP endpoints...');

  const http = require('http');

  const endpoints = [
    { path: '/health', method: 'GET', expected: 200 },
    { path: '/v1/agents', method: 'GET', expected: 200 },
    { path: '/v1/tools', method: 'GET', expected: 200 },
    { path: '/v1/observations', method: 'GET', expected: 200 }
  ];

  let allPassed = true;

  for (const endpoint of endpoints) {
    try {
      const options = {
        hostname: CONFIG.mcp.host,
        port: CONFIG.mcp.port,
        path: endpoint.path,
        method: endpoint.method,
        timeout: 5000
      };

      const response = await new Promise((resolve, reject) => {
        const req = http.request(options, (res) => {
          let data = '';
          res.on('data', chunk => data += chunk);
          res.on('end', () => resolve({ status: res.statusCode, data }));
        });

        req.on('error', reject);
        req.on('timeout', () => {
          req.destroy();
          reject(new Error('Timeout'));
        });
        req.end();
      });

      if (response.status === endpoint.expected) {
        log.success(`✓ ${endpoint.path} - ${response.status}`);
      } else {
        log.warn(`⚠ ${endpoint.path} - Expected ${endpoint.expected}, got ${response.status}`);
        allPassed = false;
      }
    } catch (error) {
      log.error(`✗ ${endpoint.path} - ${error.message}`);
      allPassed = false;
    }
  }

  return allPassed;
}

/**
 * Test tool call history endpoint
 */
async function testToolCallHistory() {
  log.step('Testing tool call history endpoint...');

  try {
    const response = await fetch(`${CONFIG.mcp.url}/v1/tools/history`, {
      method: 'GET',
      headers: {
        'Content-Type': 'application/json'
      }
    });

    if (response.ok) {
      const data = await response.json();
      log.success('✓ Tool call history endpoint working');
      return true;
    } else {
      log.warn('⚠ Tool call history endpoint returned non-200 status');
      return false;
    }
  } catch (error) {
    log.error(`✗ Tool call history endpoint failed: ${error.message}`);
    return false;
  }
}

/**
 * Main installation function
 */
async function install(mode = 'auto') {
  console.log(`\n${colors.cyan}========================================`);
  console.log(`  AgentMemory Installation Script`);
  console.log(`========================================\n`);

  // Check prerequisites
  log.step('Checking prerequisites...');

  const python = checkPython();
  if (!python.available) {
    log.error('Python 3.10+ is required. Please install Python first.');
    return false;
  }
  log.success(`Python ${python.version.trim()}`);

  // Check Docker availability
  const docker = checkDocker();
  log.info(`Docker: ${docker.available ? 'Available' : 'Not available'}`);

  // Check PostgreSQL availability
  const postgres = checkPostgres();
  log.info(`PostgreSQL: ${postgres.available ? 'Available' : 'Not available'}`);

  // Determine installation mode
  if (mode === 'auto') {
    if (docker.available) {
      log.info('Docker is available. Using Docker installation.');
      mode = 'docker';
    } else {
      log.info('Docker not available. Using local PostgreSQL installation.');
      mode = 'local';
    }
  }

  // Install based on mode
  if (mode === 'docker') {
    await installDocker();
  } else {
    await installLocal();
  }

  // Test MCP endpoints
  if (mode === 'local') {
    const mcpPassed = await testMCPEndpoints();
    if (!mcpPassed) {
      log.warn('Some MCP endpoints failed. Please check the server is running.');
    }

    const historyPassed = await testToolCallHistory();
    if (!historyPassed) {
      log.warn('Tool call history endpoint failed. Please check the server is running.');
    }
  }

  console.log(`\n${colors.cyan}========================================`);
  console.log(`  Installation Complete!`);
  console.log(`========================================\n`);

  log.info('Next steps:');
  log.info('  1. Run: node run');
  log.info('  2. Or: python smart_start.py');
  log.info('  3. Check logs in: logs/');

  return true;
}

/**
 * Install with Docker
 */
async function installDocker() {
  log.step('Installing with Docker...');

  try {
    // Pull Docker image
    execSync('docker pull metazen11/agent-memory:latest', { stdio: 'inherit' });

    // Run Docker container
    execSync(`docker run -d \
      --name agent-memory \
      -p 3377:3377 \
      -v $(pwd)/data:/app/data \
      -v $(pwd)/logs:/app/logs \
      -e POSTGRES_PASSWORD=postgres \
      metazen11/agent-memory:latest`, { stdio: 'inherit' });

    log.success('Docker container started successfully');

    // Wait for container to be ready
    log.info('Waiting for container to be ready...');
    await new Promise(resolve => setTimeout(resolve, 5000));

    // Test MCP endpoints
    await testMCPEndpoints();

  } catch (error) {
    log.error('Failed to install with Docker');
    throw error;
  }
}

/**
 * Install with local PostgreSQL
 */
async function installLocal() {
  log.step('Installing with local PostgreSQL...');

  // Install PostgreSQL based on platform
  let postgresInstalled = false;

  if (PLATFORM.isLinux) {
    postgresInstalled = await installPostgresLinux();
  } else if (PLATFORM.isMac) {
    postgresInstalled = await installPostgresMac();
  } else if (PLATFORM.isWindows) {
    postgresInstalled = await installPostgresWindows();
  }

  if (!postgresInstalled) {
    log.warn('PostgreSQL installation skipped. Please install manually.');
    log.info('Follow instructions in README.md for manual PostgreSQL setup.');
  }

  // Start PostgreSQL
  if (postgresInstalled) {
    startPostgres();
  }

  // Initialize database
  initPostgres();

  // Install Python dependencies
  installPythonDependencies();

  // Test MCP endpoints
  const mcpPassed = await testMCPEndpoints();
  if (!mcpPassed) {
    log.warn('Some MCP endpoints failed. Please check the server is running.');
  }

  const historyPassed = await testToolCallHistory();
  if (!historyPassed) {
    log.warn('Tool call history endpoint failed. Please check the server is running.');
  }
}

// CLI argument parsing
function parseArgs() {
  const args = process.argv.slice(2);
  const mode = args.find(arg => arg.startsWith('--mode='))?.split('=')[1] || 'auto';
  const skipDb = args.includes('--skip-db');
  const testMcp = args.includes('--test-mcp');

  return { mode, skipDb, testMcp };
}

// Main entry point
(async () => {
  const { mode, skipDb, testMcp } = parseArgs();

  if (skipDb) {
    log.warn('Skipping database setup. Please ensure PostgreSQL is running.');
  }

  const success = await install(mode);

  process.exit(success ? 0 : 1);
})();
