/**
 * Install PostgreSQL on Linux
 */
function installPostgresLinux() {
  log.step('Installing PostgreSQL on Linux...');

  try {
    execSync('sudo apt-get update', { stdio: 'inherit' });
    execSync('sudo apt-get install -y postgresql postgresql-contrib', { stdio: 'inherit' });
    log.success('PostgreSQL installed successfully');
    return true;
  } catch (e) {
    log.error('Failed to install PostgreSQL on Linux');
    return false;
  }
}

/**
 * Install PostgreSQL on macOS
 */
function installPostgresMac() {
  log.step('Installing PostgreSQL on macOS...');

  try {
    // Check if Homebrew is available
    if (!commandExists('brew')) {
      log.warn('Homebrew not found. Installing Homebrew...');
